const companionPrivacyCopy={"intro":"No account or identity documents are needed. Your plans and optional spending calculations run on your device. Separate online tools explain what they send before you submit.","assurance":"No account needed. Saving your plan on this browser is optional.","title":"How each tool handles your information","plans":"Plans, dates and family checklists","plansText":"These follow the Remember setting below. Saving is off by default. Anyone using this browser may see information you choose to save.","daily":"Spending amounts and everyday question choices","dailyText":"These stay only in this open page, even when Remember is on. Clearing your Lift plan also clears them. Copied text and downloaded files remain outside Lift.","online":"Research survey and experimental checker","onlineText":"These have separate notices. Read the notice before submitting anything. They need internet access."};
Object.assign(window.LiftMyanmar,{"No account or identity documents are needed. Your plans and optional spending calculations run on your device. Separate online tools explain what they send before you submit.":"အကောင့် သို့မဟုတ် ကိုယ်ရေးအထောက်အထားစာရွက်စာတမ်းများ မလိုပါ။ သင့်အစီအစဉ်များနှင့် ရွေးချယ်အသုံးပြုနိုင်သော အသုံးစရိတ်တွက်ချက်မှုများကို သင့်စက်ပေါ်တွင် လုပ်ဆောင်ပါသည်။ သီးခြားအွန်လိုင်းကိရိယာများက သင်မပို့မီ မည်သည့်အချက်အလက်များကို ပို့မည်ဖြစ်ကြောင်း ရှင်းပြပါသည်။","No account needed. Saving your plan on this browser is optional.":"အကောင့် မလိုပါ။ ဤဘရောက်ဇာတွင် သင့်အစီအစဉ်ကို သိမ်းဆည်းမည်၊ မသိမ်းဆည်းမည်ကို ရွေးချယ်နိုင်ပါသည်။","How each tool handles your information":"ကိရိယာတစ်ခုစီက သင့်အချက်အလက်များကို ကိုင်တွယ်ပုံ","Plans, dates and family checklists":"အစီအစဉ်များ၊ ရက်စွဲများနှင့် မိသားစုစစ်ဆေးရန်စာရင်းများ","These follow the Remember setting below. Saving is off by default. Anyone using this browser may see information you choose to save.":"၎င်းတို့ကို အောက်ပါ အစီအစဉ်မှတ်ထားရန် ဆက်တင်အတိုင်း သိမ်းဆည်းပါသည်။ မူလအတိုင်း သိမ်းဆည်းမှုကို ပိတ်ထားပါသည်။ ဤဘရောက်ဇာကို အသုံးပြုသူ မည်သူမဆို သင်သိမ်းဆည်းရန် ရွေးထားသော အချက်အလက်များကို မြင်နိုင်ပါသည်။","Spending amounts and everyday question choices":"အသုံးစရိတ်ပမာဏများနှင့် ရွေးထားသော နေ့စဉ်ဘဝမေးခွန်းများ","These stay only in this open page, even when Remember is on. Clearing your Lift plan also clears them. Copied text and downloaded files remain outside Lift.":"အစီအစဉ်မှတ်ထားရန် ဆက်တင်ကို ဖွင့်ထားလျှင်လည်း ၎င်းတို့သည် ယခုဖွင့်ထားသော စာမျက်နှာထဲတွင်သာ ရှိနေပါသည်။ သင့် Lift အစီအစဉ်ကို ရှင်းလင်းလျှင် ၎င်းတို့ကိုလည်း ရှင်းလင်းပါသည်။ ကူးယူထားသော စာသားနှင့် ဒေါင်းလုဒ်လုပ်ထားသော ဖိုင်များသည် Lift ပြင်ပတွင် ကျန်ရှိပါသည်။","Research survey and experimental checker":"သုတေသနစစ်တမ်းနှင့် စမ်းသပ်ဆဲ အချက်အလက်စစ်ဆေးကိရိယာ","These have separate notices. Read the notice before submitting anything. They need internet access.":"၎င်းတို့တွင် သီးခြားအသိပေးချက်များ ရှိပါသည်။ မည်သည့်အရာကိုမဆို မပို့မီ အသိပေးချက်ကို ဖတ်ပါ။ အင်တာနက်ချိတ်ဆက်မှု လိုအပ်ပါသည်။"});
/* privacy-copy:end */
// Task-first home; source and legal-status decisions remain with the person.
function taskVector(name){
 const paths={
 daily:'<rect class="vector-fill" x="7" y="8" width="27" height="25" rx="8"/><path d="M15 33l-6 6v-9M14 8h13a7 7 0 0 1 7 7v11a7 7 0 0 1-7 7H15M7 26V15a7 7 0 0 1 7-7M14 17h13m-13 7h8M34 21h2a6 6 0 0 1 6 6v7a6 6 0 0 1-6 6h-3l-5 4v-5"/>',
 family:'<circle class="vector-fill" cx="18" cy="17" r="9"/><circle cx="18" cy="17" r="7"/><circle class="vector-accent" cx="34" cy="24" r="5"/><path d="M6 40v-4a12 12 0 0 1 24 0v4M29 34a8 8 0 0 1 13 6M10 40h28"/>',
 resources:'<path class="vector-fill" d="M8 12h13l3 3 3-3h13v27H27l-3 3-3-3H8Z"/><path d="M24 15v24M8 12c6-2 11-1 16 3 5-4 10-5 16-3v27c-6-2-11-1-16 3-5-4-10-5-16-3Z"/><path d="M13 20h6m-6 6h6m10-6h6m-6 6h6"/>',
 dates:'<rect class="vector-fill" x="8" y="11" width="32" height="29" rx="7"/><rect x="8" y="11" width="32" height="29" rx="7"/><path d="M8 21h32M16 7v8m16-8v8m-16 14h4m8 0h4m-16 6h4"/><circle class="vector-accent" cx="33" cy="35" r="6"/>',
 language:'<rect class="vector-fill" x="6" y="8" width="25" height="22" rx="7"/><path d="M14 30l-5 5v-8M30 19h5a7 7 0 0 1 7 7v7a7 7 0 0 1-7 7h-4l-5 4v-5a7 7 0 0 1-6-7M13 8h11a7 7 0 0 1 7 7v8a7 7 0 0 1-7 7H14M6 24V15a7 7 0 0 1 7-7"/><path d="M12 17h13m-6-4v4m-4 0c1 5 4 7 9 9m-2-9c-1 5-4 7-9 9m16 6 3-7 3 7m-5-2h4"/>',
 prepare:'<path class="vector-fill" d="M7 10h34v24H24l-9 7v-7H7Z"/><path d="M15 34v7l9-7h10a7 7 0 0 0 7-7V16a7 7 0 0 0-7-7H14a7 7 0 0 0-7 7v11a7 7 0 0 0 7 7"/><path d="M15 18h18m-18 7h11"/><circle class="vector-accent" cx="36" cy="35" r="6"/>'
 };return `<svg class="task-vector" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name==='life'?'daily':name]||paths.prepare}</svg>`;
}
const companionBasePrivacy=privacy;
privacy=function(){
 const panel=`<section class="content-card privacy-tools"><h2>${companionPrivacyCopy.title}</h2>${[['steps','plans','plansText'],['money','daily','dailyText'],['shield','online','onlineText']].map(([symbol,title,body])=>`<div class="privacy-tool-row"><span class="privacy-tool-icon">${icon(symbol)}</span><div><h3>${companionPrivacyCopy[title]}</h3><p>${companionPrivacyCopy[body]}</p></div></div>`).join('')}</section>`;
 return companionBasePrivacy().replace('A little help should never mean giving up your privacy. This prototype asks for no account, identity documents or financial details.',companionPrivacyCopy.intro).replace('<div class="page-grid"><div>','<div class="page-grid"><div>'+panel);
};
home=function(){return `<section class="companion-welcome"><div><h1>What would help today?</h1><p>Your next step, together.</p></div>${landscape()}</section><div class="companion-tasks">${[['life','people',LiftI18n.t('Everyday life')],['family','learn',familyLabel('title')],['community','people',communityLabel('title')],['dates','steps',dateLabel('open')]].map(([path,ic,label])=>`<a class="companion-task" href="#${path}" ${path==='resources'?'data-resource-topic="all"':''}><span class="task-art">${taskVector(path)}</span><strong>${label}</strong><span class="task-direction">${icon('arrow')}</span></a>`).join('')}</div><nav class="companion-topics" aria-label="Filter information by topic">${[['work','work','Work'],['skills','learn','Learning'],['support','heart','Support']].map(([key,ic,label])=>`<a href="#resources" data-resource-topic="${key}">${icon(ic)}<span>${label}</span></a>`).join('')}</nav>${state.plan?`<a class="companion-continue" href="#steps">${icon('steps')} My next steps ${icon('arrow')}</a>`:''}<div class="companion-secondary"><a href="#prepare">Prepare a conversation ${icon('people')}</a><a href="#spending">${spendingLabel('title')} ${icon('money')}</a><a href="#language">${phaseOneTools.title} ${icon('globe')}</a><a href="#resources" data-resource-topic="all">Useful information ${icon('book')}</a><a href="#steps">${state.plan?'My next steps':'Make my first plan'} ${icon('arrow')}</a><a href="#about">About this prototype ${icon('arrow')}</a></div><p class="small-assurance">${icon('lock')}${companionPrivacyCopy.assurance}</p><div id="home-survey-slot"></div>`;};
function datesPage(){return heading('One thing at a time',dateLabel('open'),dateLabel('review'))+datePanel();}
function languagePage(){return heading('A place to explore',phaseOneTools.title,phaseOneTools.intro)+phaseOneLearningPanel(true);}
function aboutPage(){return heading('Built around people','A first step for Lift.','Lift’s ambition is to support Myanmar migrants in Thailand through access, livelihoods, steadier earnings and long-term goals.')+`<div class="journey">${stages.map((s,i)=>`<button class="journey-item" data-action="stage" data-stage="${i}"><span class="stage-number">${i+1}</span><h2>${s.title}</h2><p>${s.short}</p></button>`).join('')}</div><p>Life is not a straight line. You can return to any stage.</p><a class="secondary" href="#privacy">My privacy</a>`;}
// Decorative vectors reinforce labelled sections; they never replace the words.
function decorateCompanionSections(){
 const routeIcons={community:'people',home:'home',steps:'steps',resources:'book',dates:'steps',language:'globe',family:'learn',prepare:'people',privacy:'shield',about:'sprout',spending:'money',daily:'people'};
 const routeIcon=routeIcons[document.body.dataset.route]||'sprout';
 document.querySelectorAll('main h2').forEach((heading,index)=>{
  if(heading.querySelector('.section-vector')||heading.closest('.resource-card,.language-tool,.journey'))return;
  const badge=document.createElement('span');badge.className='section-vector';badge.setAttribute('aria-hidden','true');badge.innerHTML=icon(index===0?routeIcon:document.body.dataset.route==='privacy'?'shield':'sprout');heading.prepend(badge);
 });
 document.querySelectorAll('.family-topics .family-choice').forEach((choice,index)=>{
  if(choice.querySelector('.topic-vector'))return;
  const badge=document.createElement('span');badge.className='topic-vector';badge.setAttribute('aria-hidden','true');badge.innerHTML=icon(['learn','globe','steps','book','money','heart'][index]||'sprout');choice.insertBefore(badge,choice.querySelector('span'));
 });
 document.querySelectorAll('main .primary,main .secondary').forEach(control=>{
  if(control.querySelector('svg'))return;
  const badge=document.createElement('span');badge.className='action-vector';badge.setAttribute('aria-hidden','true');badge.innerHTML=icon(control.dataset.action?.includes('download')?'download':'arrow');control.append(badge);
 });
}
const companionBaseRoute=route;
let surveyDismissed=false;
const surveyInvite=document.querySelector('.survey-invite');
if(surveyInvite){surveyInvite.removeAttribute('style');const dismiss=document.createElement('button');dismiss.type='button';dismiss.className='text-button';dismiss.dataset.action='dismiss-survey';dismiss.textContent='Close';surveyInvite.append(dismiss);}
route=function(){companionBaseRoute();const slot=document.getElementById('home-survey-slot');if(surveyInvite){surveyInvite.hidden=!slot||surveyDismissed;if(slot&&!surveyDismissed)slot.append(surveyInvite);}LiftI18n.render();decorateCompanionSections();const count=document.getElementById('resource-count');if(count)count.textContent=LiftI18n.t('{count} matching sources',{count:document.querySelectorAll('.resource-card').length});};
document.addEventListener('click',event=>{const topic=event.target.closest('[data-resource-topic]');if(topic){event.preventDefault();resourceFilter=topic.dataset.resourceTopic;searchTerm='';navigate('#resources');return;}if(event.target.closest('[data-action="dismiss-survey"]')){surveyDismissed=true;if(surveyInvite)surveyInvite.hidden=true;}});
route();
